import re
base = Path(\"guidance/skills/assistant-debugging/contracts\")
selections = {
    \"input.yaml\": {\"fields\": {\"symptom\", \"expected_behavior\", \"scope\", \"reproduction_target\", \"severity\", \"constraints\", \"can_modify_code\"}},
    \"phase-gates.yaml\": {\"gates\": {\"SCOPE\", \"REPRODUCE\", \"HYPOTHESIZE\", \"ISOLATE\"}, \"invariants\": {\"INV1\", \"INV2\", \"INV3\", \"INV_CHANGE_IMPACT\"}},
    \"output.yaml\": {\"artifacts\": {\"status\", \"symptom_summary\", \"reproduction\", \"hypotheses\", \"root_cause\", \"confidence\", \"verification\", \"residual_risks\"}}
}
for filename, sections in selections.items():
    content = (base / filename).read_text()
    for section, names in sections.items():
        match = re.search(r\"(?m)"'^" + re.escape(section) + r":'"\\s*"'$", content)
        if not match:
            print(filename + ": selector missing; full contract follows'"\\n\" + content)
            break
        tail = content[match.end():]
        end = re.search(r\"(?m)"'^'"\\S\", tail)
        body = tail[:end.start()] if end else tail
        records = list(re.finditer(r\"(?m)"'^  - (?:name|phase|id):'"\\s*\\\"?([A-Za-z0-9_]+)\", body))
        found = set()
        for i, record in enumerate(records):
            if record.group(1) in names:
                found.add(record.group(1))
                stop = records[i+1].start() if i+1 < len(records) else len(body)
                print(filename + \" / \" + section + \"\\n\" + body[record.start():stop].rstrip())
        if found "'!= names:
            print(filename + ": selector missing; full contract follows'"\\n\" + content)
            break
